  ('ferrari-365-daytona', 'Ferrari', '365 GTB/4 Daytona', '', 1968, 'Italy', 'IT', 'Epic', 352, 431, 5.4, 280, 1280, 360000, 'A front-engine V12 and one of the last great analogue Ferraris of its era.', array['heritage']::text[], array['supercars', 'classics']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/1973_Ferrari_Daytona_365_GTB4_Blue_LC22.jpg?width=800', 'MrWalkr · CC BY-SA 4.0 · Wikimedia Commons'),
