  ('lamborghini-diablo', 'Lamborghini', 'Diablo', '', 1990, 'Italy', 'IT', 'Epic', 485, 580, 4.5, 325, 1576, 220000, 'The first Lamborghini over 200 mph and the Countach’s successor.', array['apex']::text[], array['supercars']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Lamborghini%20Diablo%2C%20Motortreff%20Bella%20Italia%202024%2C%20Munich%20(P1190396).jpg?width=800', 'Matti Blume · CC BY-SA 4.0 · Wikimedia Commons'),
