  ('subaru-impreza-sti-gdb', 'Subaru', 'Impreza WRX STI', 'GDB', 2005, 'Japan', 'JP', 'Epic', 276, 392, 5, 255, 1470, 68000, 'A 2.0 litre turbo boxer, driver-controlled centre differential and the blue-and-gold look.', array['street']::text[], array['jdm', 'rally']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Subaru%20IMPREZA%20WRX%20STi%20(GDB).jpg?width=800', 'Tokumeigakarinoaoshima · CC BY-SA 4.0 · Wikimedia Commons'),
