  ('mercedes-sls-amg', 'Mercedes-Benz', 'SLS AMG', '', 2010, 'Germany', 'DE', 'Epic', 563, 650, 3.8, 317, 1620, 150000, 'A gullwing 6.2 litre V8 with a long bonnet that is a nod to the 300 SL.', array['apex']::text[], array['supercars']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Mercedes-Benz_SLS_AMG_(C_197)_%E2%80%93_Frontansicht_ge%C3%B6ffnet%2C_10._August_2011%2C_D%C3%BCsseldorf.jpg?width=800', 'M 93 · CC BY-SA 3.0 de · Wikimedia Commons'),
  ('audi-r8-v8', 'Audi', 'R8', 'Type 42', 2006, 'Germany', 'DE', 'Epic', 420, 430, 4.6, 301, 1560, 105000, 'A mid-engine, all-wheel-drive supercar that was easy to drive every day.', array['apex']::text[], array['supercars']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Audi%20R8-08.jpg?width=800', 'Thhe, edited by אx · CC BY 2.5 · Wikimedia Commons'),
