  ('mclaren-p1', 'McLaren', 'P1', '', 2013, 'United Kingdom', 'GB', 'Legendary', 903, 900, 2.8, 350, 1395, 1300000, 'A hybrid hypercar with a drag-reduction system and a formidable track-day record.', array['apex']::text[], array['supercars', 'concepts']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/2013%20McLaren%20P1.jpg?width=800', 'MrWalkr · CC BY-SA 4.0 · Wikimedia Commons'),
