  ('koenigsegg-ccx', 'Koenigsegg', 'CCX', '', 2006, 'Sweden', 'SE', 'Legendary', 806, 920, 3.2, 395, 1180, 750000, 'Koenigsegg’s own engine, developed for the American market.', array['apex']::text[], array['supercars', 'concepts']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Koenigsegg_CCX_-_Flickr_-_Alexandre_Pr%C3%A9vot_(11).jpg?width=800', 'Alexandre Prévot from Nancy, France · CC BY-SA 2.0 · Wikimedia Commons'),
